"""Random campaign generator for offline cross-checking (development only)."""
import base64, hashlib, io, ipaddress, json, plistlib, random, struct, sys
sys.path.insert(0, '/workspace/deps')
import zstandard as zstd

DOC = ipaddress.IPv6Network('2001:db8::/32')
HEADER = 'type,id,revision,published,op,lease,event,probe,target,responder,result,service,attempt,payload'


def rid(rng, prefix, n):
    return '%s%d' % (prefix, n)


def align(rng, bits):
    base = int(DOC.network_address)
    span = 1 << 128
    step = 1 << (128 - bits)
    count = (span - base) >> (128 - bits)
    return base + step * rng.randrange(1, max(2, count))


def make_adb(rng, kind='CNXN', corrupt=None):
    CNXN, AUTH, CLSE = 0x4e584e43, 0x48545541, 0x45534c43
    command = {'CNXN': CNXN, 'AUTH': AUTH, 'CLSE': CLSE}[kind]
    arg0 = rng.choice([0x01000000, 0x01000001, 0x02000000, rng.randrange(1 << 32)])
    arg1 = rng.choice([0, 4096, rng.randrange(1 << 16)])
    if command == CNXN:
        body = rng.choice([b'host::zgrab2', 'héllo'.encode(), b'', b'dev::usb'])
    else:
        body = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 8)))
    length = len(body)
    check = sum(body) & 0xffffffff
    magic = command ^ 0xffffffff
    if corrupt == 'checksum':
        check = (check + 1) & 0xffffffff
    elif corrupt == 'magic':
        magic ^= 1
    elif corrupt == 'length':
        length += 1
    elif corrupt == 'extra':
        body += b'x'
    packet = struct.pack('<6I', command, arg0, arg1, length, check, magic) + body
    return packet


def make_sync(rng, keys=('ProductVersion', 'ProductName'), corrupt=None, fmt=plistlib.FMT_XML):
    frames = []
    for i, key in enumerate(keys):
        value = rng.choice(['17.1.1', 'iPhone', 'x' * 3, '1.0'])
        obj = {'Key': key, 'Request': 'GetValue', 'Value': value}
        if corrupt == 'fields' and i == 0:
            obj = {'Key': key, 'Request': 'GetValue', 'Value': value, 'Label': 'usb'}
        if corrupt == 'empty' and i == 0:
            obj['Value'] = ''
        if corrupt == 'request' and i == 0:
            obj['Request'] = 'SetVersion'
        body = plistlib.dumps(obj, fmt=fmt)
        frames.append(struct.pack('>I', len(body)) + body)
    data = b''.join(frames)
    if corrupt == 'trailing':
        data += b'\x00'
    if corrupt == 'short':
        data = data[:4]
    return data


class Builder:
    def __init__(self, seed=None):
        self.rng = random.Random(seed)
        rng = self.rng
        self.seed_id = rid(rng, 'sd', rng.randrange(99))
        self.leases = []
        self.services = []
        self.queries = sorted(rng.sample(range(10, 500), rng.randrange(1, 4)))
        self.records = []
        self.extra_rows = []
        nleases = rng.randrange(0, 5)
        for i in range(nleases):
            bits = rng.choice([56, 56, 64])
            net = ipaddress.IPv6Network((align(rng, bits), bits))
            subnets = [0] if bits == 64 else sorted(rng.sample(range(256), rng.randrange(1, 4)))
            self.leases.append({'id': rid(rng, 'L', i), 'prefix': str(net),
                                'start': rng.randrange(0, 50),
                                'end': rng.randrange(400, 900),
                                'subnets': subnets, 'low_count': rng.randrange(1, 4)})
        for i, kind in enumerate(rng.sample(['tcp', 'adb', 'sync'], rng.randrange(0, 4))):
            self.services.append({'id': rid(rng, 'S', i), 'kind': kind})

    def manifest(self):
        rows = []
        for lease in sorted(self.leases, key=lambda x: x['id']):
            net = ipaddress.IPv6Network(lease['prefix'], strict=True)
            base = int(net.network_address)
            for subnet in sorted(lease['subnets']):
                n64 = base + (subnet << 64)
                text = str(ipaddress.IPv6Network((n64, 64)))
                material = (self.seed_id + '\n' + lease['id'] + '\n' + text).encode()
                canary = int.from_bytes(hashlib.sha256(material).digest()[:8], 'big') | (1 << 63)
                yield_ = [(lease['id'], '%d/c' % subnet, n64 + canary, True)]
                for i in range(1, lease['low_count'] + 1):
                    yield_.append((lease['id'], '%d/i%d' % (subnet, i), n64 + i, False))
                rows.extend(yield_)
        return rows

    def add_icmp(self, row, revision, published, op='put', result=None, responder=None,
                 target=None, bad=None):
        lease, probe, target_int, is_canary = row
        if result is None:
            result = self.rng.choice(['echo', 'echo', 'echo', 'error', 'timeout'])
        if responder is None:
            if result == 'timeout':
                responder = ''
            elif result == 'echo':
                responder = target_int if self.rng.random() < .75 else _near(self.rng, target_int)
            else:
                responder = target_int if self.rng.random() < .5 else _near(self.rng, target_int)
        event = self.rng.randrange(lease_event_range(self.leases, lease))
        if bad == 'fields':
            self.extra_rows.append(['icmp', 'x1'] + [''] * 5)
            return
        values = ['icmp', bad or rid(self.rng, 'r', self.rng.randrange(10000)), revision, published,
                  op, lease, event, probe,
                  '' if target is None and op == 'put' else ('' if op == 'delete' else _text(target_int if target is None else target)),
                  '' if op == 'delete' else (responder if result else ''),
                  '' if op == 'delete' else result, '', '', '']
        if op == 'delete':
            values = values[:5] + [''] * 9
        self.records.append(values)

    def add_app(self, lease_id, target_int, service, attempt, result, payload=b'',
                published=1, revision=0, event=None, name=None, rng=None):
        rng = rng or self.rng
        event = rng.randrange(400) if event is None else event
        values = ['app', name or rid(rng, 'a', rng.randrange(10000)), revision, published, 'put',
                  lease_id, event, '', _text(target_int), '', result, service, attempt,
                  base64.b64encode(payload).decode() if payload else '']
        self.records.append(values)

    def csv_text(self):
        rows = [self.rng.permutation(self.records).tolist()] if False else self.records
        out = [HEADER]
        for values in self.rng.sample(rows, len(rows)) if len(rows) > 1 else rows:
            out.append(','.join(str(x) for x in values))
        return ('\r\n'.join(out) + '\r\n').encode()

    def captures(self, split=True):
        blob = self.csv_text()
        rng = self.rng
        if rng.random() < .5:
            data = zstd.ZstdCompressor(level=rng.choice([1, 3, 12]),
                                       write_checksum=rng.random() < .5).compress(blob)
            if rng.random() < .3:
                data = data + zstd.ZstdCompressor().compress(b'')
            encoding = 'zstd'
        else:
            data, encoding = blob, 'csv'
        chunks = []
        if split and len(data):
            cuts = sorted(rng.sample(range(1, len(data)), min(len(data), rng.randrange(1, 5)))) \
                if len(data) > 2 else []
            previous = 0
            for cut in cuts + [len(data)]:
                chunks.append(base64.b64encode(data[previous:cut]).decode())
                previous = cut
        else:
            chunks = [base64.b64encode(data).decode()]
        return [{'encoding': encoding, 'chunks': chunks}]


def lease_event_range(leases, lease_id):
    for lease in leases:
        if lease['id'] == lease_id:
            return lease['start'], lease['end']
    return 0, 1


def _near(rng, value):
    return value + rng.choice([-3, -1, 1, 2, 5, 9])


def _text(value):
    if isinstance(value, str):
        return value
    return str(ipaddress.IPv6Address(value & ((1 << 128) - 1)))
